package cc.thevar.blukit.domain.model.intelligence

import kotlinx.serialization.Serializable

/**
 * A synthesized insight of a Group generated by local Assistant.
 */
@Serializable
data class Synthesis(
    val groupId: String,
    val summary: String,
    val trendLabel: String? = null,
    val topKeywords: List<String>,
    val sentimentScore: Float, // -1.0 to 1.0
    val derivedTimestamp: Long,
    val messageCountSampled: Int
)
